CREATE VIEW `corp_portal`.`b_uts_tasks_task_v` (`№ задачи` Int64, `Название` String, `Дата создания` DateTime, `Дата изменения` Nullable(DateTime), `Бренд` Nullable(String), `Юр. лицо` Nullable(String), `Исполнитель` Nullable(String), `Постановщик` Nullable(String), `Затрачено минут` Nullable(Float64), `Проект задачи` Nullable(String), `Проект задачи родителя` Nullable(String), `Проект для оплаты` Nullable(String), `Эпик` Nullable(String), `Метка` String) AS WITH b_uts_tasks_task AS (SELECT VALUE_ID, arrayJoin(arrayFilter((element, index) -> (index NOT IN range(1, 101, 2)), splitByString('i', substring(replaceRegexpAll(butt.UF_TASK_BRAND, '[a;:{}]', ''), 3)), arrayEnumerate(splitByString('i', substring(replaceRegexpAll(butt.UF_TASK_BRAND, '[a;:{}]', ''), 3))))) AS TASK_BRAND FROM `corp_portal`.b_uts_tasks_task_mysql AS butt), b_uts_tasks_brand AS (SELECT VALUE_ID, if(replaceRegexpAll(arrayStringConcat(groupArray(bufe.VALUE), ', '), '[, ]', '') = '', '', arrayStringConcat(groupArray(bufe.VALUE), ', ')) AS TASK_BRANDS FROM b_uts_tasks_task AS tbm LEFT JOIN `corp_portal`.b_user_field_enum_mysql AS bufe ON toString(bufe.ID) = tbm.TASK_BRAND GROUP BY VALUE_ID), b_tasks_tag AS (SELECT bttt.TASK_ID, groupArray(btl.NAME) AS NAMES FROM `corp_portal`.b_tasks_task_tag_mysql AS bttt LEFT JOIN `corp_portal`.b_tasks_label_mysql AS btl ON btl.ID = bttt.TAG_ID GROUP BY bttt.TASK_ID), projects AS (SELECT utm.VALUE_ID, utm.VALUE, crm.TITLE FROM `corp_portal`.b_utm_tasks_task_mysql AS utm LEFT JOIN `corp_portal`.b_crm_dynamic_items_1048_mysql AS crm ON crm.ID = toInt32(utm.VALUE) WHERE utm.FIELD_ID = 400), projects_agg AS (SELECT VALUE_ID, arrayStringConcat(groupArray(TITLE), ', ') AS PROJECTS FROM projects GROUP BY VALUE_ID) SELECT bt.ID AS `№ задачи`, bt.TITLE AS `Название`, bt.CREATED_DATE AS `Дата создания`, btet.CREATED_DATE AS `Дата изменения`, butbr.TASK_BRANDS AS `Бренд`, ibe.NAME AS `Юр. лицо`, if(bu.LAST_NAME = '', bu.LOGIN, concat(bu.LAST_NAME, ' ', bu.NAME)) AS `Исполнитель`, if(bu_cr.LAST_NAME = '', bu_cr.LOGIN, concat(bu_cr.LAST_NAME, ' ', bu_cr.NAME)) AS `Постановщик`, btet.SECONDS / 60 AS `Затрачено минут`, bsgm.NAME AS `Проект задачи`, bsgm_p.NAME AS `Проект задачи родителя`, pr.PROJECTS AS `Проект для оплаты`, bsce.NAME AS `Эпик`, arrayStringConcat(btt.NAMES, ', ') AS `Метка` FROM `corp_portal`.b_tasks_mysql AS bt LEFT JOIN `corp_portal`.b_uts_tasks_task_mysql AS butt ON butt.VALUE_ID = bt.ID LEFT JOIN `corp_portal`.b_iblock_element_mysql AS ibe ON butt.UF_LEGAL_ENTITY = toString(ibe.ID) LEFT JOIN b_uts_tasks_brand AS butbr ON butbr.VALUE_ID = bt.ID LEFT JOIN `corp_portal`.b_tasks_elapsed_time_mysql AS btet ON btet.TASK_ID = bt.ID LEFT JOIN `corp_portal`.b_user_mysql AS bu ON bu.ID = btet.USER_ID LEFT JOIN `corp_portal`.b_user_mysql AS bu_cr ON bu_cr.ID = bt.CREATED_BY LEFT JOIN `corp_portal`.b_sonet_group_mysql AS bsgm ON bsgm.ID = bt.GROUP_ID LEFT JOIN `corp_portal`.b_tasks_mysql AS bt2 ON bt2.ID = bt.PARENT_ID LEFT JOIN `corp_portal`.b_sonet_group_mysql AS bsgm_p ON bsgm_p.ID = bt2.GROUP_ID LEFT JOIN `corp_portal`.b_tasks_scrum_item_mysql AS bsci ON bsci.SOURCE_ID = bt.ID LEFT JOIN `corp_portal`.b_tasks_scrum_epic_mysql AS bsce ON bsce.ID = bsci.EPIC_ID LEFT JOIN projects_agg AS pr ON pr.VALUE_ID = bt.ID LEFT JOIN b_tasks_tag AS btt ON btt.TASK_ID = bt.ID WHERE `Дата создания` < today() SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `corp_portal`.`jira_and_portal_time` (`№ задачи` String, `Название` Nullable(String), `Год-месяц` Nullable(Date), `Бренд` Nullable(String), `Юр. лицо` Nullable(String), `Исполнитель` Nullable(String), `Постановщик` Nullable(String), `Затрачено минут` Nullable(Decimal(38, 4)), `Часы` Nullable(Decimal(38, 4)), `Проект задачи` Nullable(String), `Проект задачи родителя` Nullable(String), `Проекты для оплаты` Nullable(String), `Эпик` Nullable(String), `Метка` String, `Проект ИТ бюджета` Nullable(String), `Контрагент` Nullable(String), `Тип услуг` Nullable(String), `Направление` Nullable(String), `Ответсвенный за работы` Nullable(String), `Источник` String, `Плательщик` Nullable(String)) AS WITH jira_data AS (SELECT `№ задачи`, `Название`, toStartOfMonth(`Дата изменения`) AS `Год-месяц`, `Бренд`, `Юр. лицо`, `Исполнитель`, `Постановщик`, sum(`Затрачено минут`) AS `Затрачено минут`, `Проект задачи`, `Проект задачи родителя`, `Проект для оплаты` AS `Проекты для оплаты`, `Эпик`, arrayStringConcat(groupUniqArray(`Метка`), ', ') AS `Метка`, 'JIRA' AS `Выгруженно` FROM `corp_portal`.time_jira_portal GROUP BY `№ задачи`, `Название`, toStartOfMonth(`Дата изменения`), `Бренд`, `Юр. лицо`, `Исполнитель`, `Постановщик`, `Проект задачи`, `Проект задачи родителя`, `Проект для оплаты`, `Эпик`, `Выгруженно` HAVING `Затрачено минут` > 0), portal_data AS (SELECT toString(`№ задачи`) AS `№ задачи`, `Название`, toStartOfMonth(`Дата изменения`) AS `Год-месяц`, `Бренд`, `Юр. лицо`, `Исполнитель`, `Постановщик`, sum(`Затрачено минут`) AS `Затрачено минут`, `Проект задачи`, `Проект задачи родителя`, `Проект для оплаты` AS `Проекты для оплаты`, `Эпик`, arrayStringConcat(groupUniqArray(`Метка`), ', ') AS `Метка`, 'Портал' AS `Выгруженно` FROM `corp_portal`.time_corp_portal GROUP BY `№ задачи`, `Название`, toStartOfMonth(`Дата изменения`), `Бренд`, `Юр. лицо`, `Исполнитель`, `Постановщик`, `Проект задачи`, `Проект задачи родителя`, `Проекты для оплаты`, `Эпик`, `Выгруженно` HAVING `Затрачено минут` > 0), jira_data_pr AS (SELECT d.*, multiIf((lower(trimBoth(m.`Эпик`)) = lower(trimBoth(d.`Эпик`))) AND (lower(trimBoth(m.`Юр. лицо`)) = lower(trimBoth(d.`Юр. лицо`))) AND (lower(trimBoth(m.`Метка`)) = lower(trimBoth(d.`Метка`))), m.`Проект ИТ бюджета`, (m.`Эпик` IS NULL) AND (d.`Эпик` IS NULL), m.`Проект ИТ бюджета`, (m.`Эпик` IS NULL) AND (NOT (d.`Эпик` IS NULL)), m.`Проект ИТ бюджета`, NULL) AS `Проект ИТ бюджета jira` FROM jira_data AS d LEFT JOIN `corp_portal`.projets_mapping AS m ON (lower(trimBoth(m.`Проект JIRA`)) = lower(trimBoth(d.`Проект задачи`))) AND (lower(trimBoth(m.`Юр. лицо`)) = lower(trimBoth(d.`Юр. лицо`))) SETTINGS join_use_nulls = 1), base_table AS (SELECT *, NULL AS `Проект ИТ бюджета jira` FROM portal_data WHERE (`Год-месяц` >= '2020-01-01') AND (`Год-месяц` <= toStartOfMonth(today())) UNION ALL SELECT * FROM jira_data_pr WHERE (`Год-месяц` >= '2020-01-01') AND (`Год-месяц` <= toStartOfMonth(today()))), base_table_with_employees AS (SELECT b.*, multiIf(`Проект ИТ бюджета jira` IS NOT NULL, `Проект ИТ бюджета jira`, (`Проекты для оплаты` NOT IN ('', '-')) AND (`Проекты для оплаты` IS NOT NULL), `Проекты для оплаты`, (`Проекты для оплаты` IN ('', '-')) OR (`Проекты для оплаты` IS NULL), `Проект задачи`, (`Проект задачи` IN ('', '-')) OR (`Проект задачи` IS NULL), `Проект задачи родителя`, (`Проект задачи родителя` IN ('', '-')) OR (`Проект задачи родителя` IS NULL), `Эпик`, NULL) AS `Проект для бюджета`, e.`Организация` AS `Контрагент`, e.`Тип услуг` AS `Тип услуг`, e.`Направление` AS `Направление`, e.`Ответсвенный за работы` AS `Ответсвенный за работы`, ifNull(e.`Источник`, b.`Выгруженно`) AS `Источник` FROM base_table AS b LEFT JOIN `corp_portal`.employees AS e FINAL ON replaceAll(lower(e.`Сотрудник`), ' ', '') = replaceAll(lower(b.`Исполнитель`), ' ', '')) SELECT `№ задачи`, `Название`, `Год-месяц`, `Бренд`, `Юр. лицо`, `Исполнитель`, `Постановщик`, if(p.`Доля` IS NOT NULL, toDecimal32(`Затрачено минут` * p.`Доля`, 2) * toDecimal32(0.01, 2), `Затрачено минут`) AS `Затрачено минут`, round(if(p.`Доля` IS NOT NULL, toDecimal32(`Затрачено минут` * p.`Доля`, 2) * toDecimal32(0.01, 2), `Затрачено минут`) / 60, 2) AS `Часы`, `Проект задачи`, `Проект задачи родителя`, `Проекты для оплаты`, `Эпик`, `Метка`, if(`Проект ИТ бюджета jira` IS NULL, m.`Проект ИТ бюджета`, `Проект ИТ бюджета jira`) AS `Проект ИТ бюджета`, `Контрагент`, `Тип услуг`, `Направление`, `Ответсвенный за работы`, `Источник`, multiIf(p.`Плательщик` = 'ДО', 'Дом одежды', p.`Плательщик` = 'СК', 'Сезонная коллекция', p.`Плательщик` = 'MG', 'Мюнц Групп', p.`Плательщик` = 'MS', 'Радость', NULL) AS `Плательщик` FROM base_table_with_employees AS b LEFT JOIN (SELECT DISTINCT p.`Проект`, p.`Проект ИТ бюджета` FROM `corp_portal`.projects AS p FINAL) AS m ON lower(trimBoth(m.`Проект`)) = lower(trimBoth(b.`Проект для бюджета`)) LEFT JOIN `corp_portal`.projects AS p FINAL ON (lower(trimBoth(p.`Проект`)) = lower(trimBoth(b.`Проект для бюджета`))) AND (p.`Доля` > 0) SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `corp_portal`.`jira_and_portal_time_simple` (`№ задачи` String, `Название` Nullable(String), `Год-месяц` Nullable(Date), `Бренд` Nullable(String), `Юр. лицо` Nullable(String), `Исполнитель` Nullable(String), `Постановщик` Nullable(String), `Затрачено минут` Nullable(Int64), `Проект задачи` Nullable(String), `Проект задачи родителя` Nullable(String), `Проекты для оплаты` Nullable(String), `Эпик` Nullable(String), `Метка` Nullable(String), `Выгруженно` String, `Контрагент` Nullable(String), `Тип услуг` Nullable(String), `Направление` Nullable(String), `Ответсвенный за работы` Nullable(String), `Источник` String) AS WITH jira_data AS (SELECT `№ задачи`, `Название`, toStartOfMonth(`Дата изменения`) AS `Год-месяц`, `Бренд`, `Юр. лицо`, `Исполнитель`, `Постановщик`, sum(`Затрачено минут`) AS `Затрачено минут`, `Проект задачи`, `Проект задачи родителя`, `Проект для оплаты` AS `Проекты для оплаты`, `Эпик`, `Метка`, 'JIRA' AS `Выгруженно` FROM `corp_portal`.time_jira_portal GROUP BY `№ задачи`, `Название`, toStartOfMonth(`Дата изменения`), `Бренд`, `Юр. лицо`, `Исполнитель`, `Постановщик`, `Проект задачи`, `Проект задачи родителя`, `Проекты для оплаты`, `Эпик`, `Метка`, `Выгруженно` HAVING `Затрачено минут` > 0), portal_data AS (SELECT toString(`№ задачи`) AS `№ задачи`, `Название`, toStartOfMonth(`Дата изменения`) AS `Год-месяц`, `Бренд`, `Юр. лицо`, `Исполнитель`, `Постановщик`, sum(`Затрачено минут`) AS `Затрачено минут`, `Проект задачи`, `Проект задачи родителя`, `Проект для оплаты` AS `Проекты для оплаты`, `Эпик`, `Метка` AS `Метка`, 'Портал' AS `Выгруженно` FROM `corp_portal`.time_corp_portal GROUP BY `№ задачи`, `Название`, toStartOfMonth(`Дата изменения`), `Бренд`, `Юр. лицо`, `Исполнитель`, `Постановщик`, `Проект задачи`, `Проект задачи родителя`, `Проекты для оплаты`, `Эпик`, `Метка`, `Выгруженно` HAVING `Затрачено минут` > 0), base_table AS (SELECT * FROM portal_data WHERE (`Год-месяц` >= toStartOfMonth(today() - toIntervalMonth(2))) AND (`Год-месяц` <= toStartOfMonth(today())) UNION ALL SELECT * FROM jira_data WHERE (`Год-месяц` >= toStartOfMonth(today() - toIntervalMonth(2))) AND (`Год-месяц` <= toStartOfMonth(today()))) SELECT b.*, e.`Организация` AS `Контрагент`, e.`Тип услуг` AS `Тип услуг`, e.`Направление` AS `Направление`, e.`Ответсвенный за работы` AS `Ответсвенный за работы`, ifNull(e.`Источник`, b.`Выгруженно`) AS `Источник` FROM base_table AS b LEFT JOIN `corp_portal`.employees AS e FINAL ON replaceAll(lower(e.`Сотрудник`), ' ', '') = replaceAll(lower(b.`Исполнитель`), ' ', '') WHERE e.`Ответсвенный за работы` IS NOT NULL SETTINGS join_use_nulls = 1, final = 1;

